{"content": "# -*- coding: utf-8 -*-
"""尝试多种策略获取 B 站 UP 主投稿列表，并输出 UTF-8 结果。"""
import json, time, hashlib, urllib.parse, urllib.request, os, sys, base64

UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36"
MIXIN_TAB = [46,47,18,2,53,8,23,32,15,50,10,31,58,3,45,35,27,43,5,49,33,9,42,19,29,28,14,39,12,38,41,13,37,48,7,16,24,55,40,61,26,17,0,1,60,51,30,4,22,25,54,21,56,59,6,63,57,62,11,36,20,34,44,52]

COOKIES = {}

def req(url, params=None):
    if params:
        url += "?" + urllib.parse.urlencode(params)
    h = {"User-Agent": UA, "Referer": "https://space.bilibili.com/", "Accept": "application/json, text/plain, */*"}
    if COOKIES:
        h["Cookie"] = "; ".join(f"{k}={v}" for k, v in COOKIES.items())
    r = urllib.request.Request(url, headers=h)
    with urllib.request.urlopen(r, timeout=25) as resp:
        return json.loads(resp.read().decode("utf-8"))

def init_cookie():
    try:
        d = req("https://api.bilibili.com/x/frontend/finger/spi")
        COOKIES["buvid3"] = d["data"]["b_3"]
        COOKIES["buvid4"] = d["data"]["b_4"]
    except Exception as e:
        print("spi fail", repr(e))

def wbi():
    nav = req("https://api.bilibili.com/x/web-interface/nav")
    w = nav["data"]["wbi_img"]
    img = w["img_url"].rsplit("/", 1)[-1].split(".")[0]
    sub = w["sub_url"].rsplit("/", 1)[-1].split(".")[0]
    mk = "".join((img + sub)[i] for i in MIXIN_TAB)[:32]
    return mk

def wbi_sign(params, mk):
    params = dict(params)
    params["wts"] = int(time.time())
    q = urllib.parse.urlencode(sorted(params.items()))
    params["w_rid"] = hashlib.md5((q + mk).encode()).hexdigest()
    return params

def dm_params():
    return {
        "dm_img_list": "[]",
        "dm_img_str": "V2ViR0wgMS4wIChPcGVuR0wgRVMgMi4wIENocm9taXVtKQ",
        "dm_cover_img_str": "QU5HTEUgKE5WSURJQSwgTlZJRElBIEdlRm9yY2UgR1RYIDEwNjAgNkdCIERpcmVjdDNEMTEgdnNfNV8wIHBzXzVfMCwgRDNEMTEpR29vZ2xlIEluYy4gKE5WSURJQS",
        "dm_img_inter": '{"ds":[],"wh":[0,0,0],"of":[0,0,0]}',
    }

def try_list(mid, mk):
    strategies = [
        ("wbi+dm", "https://api.bilibili.com/x/space/wbi/arc/search",
         dict({"mid": mid, "ps": 50, "pn": 1, "order": "pubdate", "platform": "web"}, **dm_params())),
        ("wbi", "https://api.bilibili.com/x/space/wbi/arc/search",
         {"mid": mid, "ps": 50, "pn": 1, "order": "pubdate", "platform": "web"}),
        ("v1", "https://api.bilibili.com/x/space/arc/search",
         {"mid": mid, "ps": 50, "pn": 1, "order": "pubdate"}),
    ]
    for name, url, base in strategies:
        try:
            p = wbi_sign(base, mk) if "wbi" in url else base
            d = req(url, p)
            code = d.get("code")
            lst = ((d.get("data") or {}).get("list") or {}).get("vlist") or []
            print(f"  {name}: code={code} n={len(lst)} msg={d.get('message')}")
            if code == 0 and lst:
                return lst
        except Exception as e:
            print(f"  {name}: EXC {e!r}")
        time.sleep(1.2)
    return []

if __name__ == "__main__":
    init_cookie()
    print("cookie keys", list(COOKIES))
    mk = wbi()
    mid = int(sys.argv[1]) if len(sys.argv) > 1 else 8479482
    vids = try_list(mid, mk)
    for v in vids[:20]:
        print(v.get("bvid"), v.get("play"), v.get("title"))
