"""通过 B 站搜索 API 抓取各 UP 相关视频（按作者 mid 过滤），输出 UTF-8 JSON。"""
import json, time, sys, os, io
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding="utf-8")
sys.path.insert(0, os.path.dirname(__file__))
import bili_try as b

UPS = {
    "2078781964": "好人松松",
    "2100737396": "凯圣王",
    "3546393006312379": "真理之弓-运动营养",
    "364281292": "陈石-营养-运动",
    "521903482": "谭成义",
    "8479482": "恶鼠变量Daiki",
    "378067652": "Gandy__",
}

def main():
    b.init_cookie()
    mk = b.wbi()
    out = {}
    for mid, name in UPS.items():
        seen, vids = set(), []
        for kw in [name, name.replace("__", ""), name.split("-")[0]]:
            if not kw:
                continue
            for page in range(1, 6):
                p = b.wbi_sign({"search_type": "video", "keyword": kw, "page": page, "order": "totalrank"}, mk)
                try:
                    d = b.req("https://api.bilibili.com/x/web-interface/wbi/search/type", p)
                except Exception as e:
                    print(name, kw, page, "EXC", repr(e)); break
                if d.get("code") != 0:
                    print(name, kw, page, "code", d.get("code")); break
                res = (d.get("data") or {}).get("result") or []
                for r in res:
                    if str(r.get("mid")) != mid:
                        continue
                    bv = r.get("bvid")
                    if bv in seen:
                        continue
                    seen.add(bv)
                    vids.append({k: r.get(k) for k in
                                 ("bvid", "title", "description", "play", "duration",
                                  "pubdate", "author", "mid", "tag", "arcurl")})
                time.sleep(1.4)
                if len(res) < 20:
                    break
        out[mid] = {"name": name, "videos": vids}
        print(name, "collected", len(vids))
        time.sleep(2)

    path = os.path.join(os.path.dirname(__file__), "..", "data", "bili_videos.json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(out, f, ensure_ascii=False, indent=1)
    print("saved", path)

if __name__ == "__main__":
    main()
