p = r'C:\Users\24380\.dsh\integrations\dsh-im\group-history.sqlite'
c = sqlite3.connect(p)
tables = [r[0] for r in c.execute("select name from sqlite_master where type='table'")]
print('TABLES', tables)
for t in tables:
    cols = [r[1] for r in c.execute(f'pragma table_info("{t}")')]
    n = c.execute(f'select count(*) from "{t}"').fetchone()[0]
    print('---', t, 'rows=', n, 'cols=', cols)
    try:
        rows = c.execute(f'select * from "{t}" limit 5').fetchall()
        for row in rows:
            print('   ', str(row)[:600])
    except Exception as e:
        print('   ERR', e)
", "file_path": "C:\Users\24380\AppData\Local\Temp\inspect_im.py"}

