{"content": """"每天生成训练提醒并通过 DSH-IM 主动投递发送到微信。

用法：
  python coach_push.py --dry            只打印，不发送
  python coach_push.py --send           生成并发送（需要 coach_config.json 里配好 botId/targetId）
  python coach_push.py --day push       强制指定某天（push/pull/legs/cardioA/cardioB/rest）
  python coach_push.py --date 2026-11-24  指定日期（默认今天）

数据来源：
  coach_plan.json        训练计划与补剂
  ../tools/训练日志模板.xlsx  训练日志（sheet「训练日志」），用于读取上次重量并计算渐进
  coach_config.json      微信投递参数 { botId, targetId, endpoint }
"""

import argparse
import datetime as dt
import json
import sys
import urllib.request
from pathlib import Path

try:
    from openpyxl import load_workbook
except Exception:  # openpyxl 不存在时仍可生成计划，只是读不到历史
    load_workbook = None

BASE = Path(__file__).resolve().parent
PLAN_PATH = BASE / "coach_plan.json"
CONFIG_PATH = BASE / "coach_config.json"
LOG_PATH = BASE.parent / "tools" / "训练日志模板.xlsx"

WEEKDAY_KEYS = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]
WEEKDAY_CN = ["周一", "周二", "周三", "周四", "周五", "周六", "周日"]


def load_json(path):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


def parse_reps(value):
    """把 '8/8/7'、'8,8,7'、8 解析成 [8,8,7]。"""
    if value is None:
        return []
    if isinstance(value, (int, float)):
        return [int(value)]
    s = str(value).replace("，", ",").replace("/", ",").replace("、", ",")
    out = []
    for part in s.split(","):
        part = part.strip()
        if not part:
            continue
        try:
            out.append(int(float(part)))
        except ValueError:
            continue
    return out


def parse_number(value):
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    s = str(value).strip().replace("kg", "").replace("KG", "")
    try:
        return float(s)
    except ValueError:
        return None


def read_last_records():
    """动作名 -> 最近一条 {date, weight, reps, rir}。"""
    records = {}
    if load_workbook is None or not LOG_PATH.exists():
        return records
    try:
        wb = load_workbook(LOG_PATH, data_only=True)
        if "训练日志" not in wb.sheetnames:
            return records
        ws = wb["训练日志"]
        for row in ws.iter_rows(min_row=2, values_only=True):
            if not row or len(row) < 7:
                continue
            date_v, _, action, _, weight_v, reps_v, rir_v = row[:7]
            if not action:
                continue
            weight = parse_number(weight_v)
            reps = parse_reps(reps_v)
            if weight is None or not reps:
                continue
            rir = parse_number(rir_v)
            if isinstance(date_v, dt.datetime):
                date_s = date_v.date().isoformat()
            else:
                date_s = str(date_v) if date_v else ""
            name = str(action).strip()
            prev = records.get(name)
            if prev is None or date_s >= prev["date"]:
                records[name] = {"date": date_s, "weight": weight, "reps": reps, "rir": rir}
    except Exception:
        return records
    return records


def fmt_num(n):
    if n is None:
        return "-"
    if abs(n - round(n)) < 1e-9:
        return str(int(round(n)))
    return f"{n:g}"


def target_for(item, last):
    """返回 (target_weight, target_reps_text, progress_note)。"""
    if not last:
        return None, f"{item['lo']}–{item['hi']} 次", "首次：选一个能完成 {} 次、还剩约 {} 次余力的重量".format(item["hi"], item["rir"])
    weight = last["weight"]
    reps = last["reps"]
    top = item["hi"]
    rir_ok = last["rir"] is None or last["rir"] <= 2
    if reps and min(reps) >= top and rir_ok:
        new_weight = weight + item["inc"]
        return new_weight, f"{item['lo']}–{item['hi']} 次", f"上次 {fmt_num(weight)}kg×{'/'.join(map(str, reps))} 已达标 → 加重到 {fmt_num(new_weight)}kg"
    return weight, f"{item['lo']}–{item['hi']} 次", f"上次 {fmt_num(weight)}kg×{'/'.join(map(str, reps))} → 今天保持 {fmt_num(weight)}kg，把次数做满"


def build_message(plan, day_key, day, date_obj, records):
    title = day["title"]
    header = f"🏋️ {date_obj.month}月{date_obj.day}日 {WEEKDAY_CN[date_obj.weekday()]} · {title}"
    lines = [header, "━━━━━━━━━━━━"]

    if day["type"] == "strength":
        for i, item in enumerate(day["items"], 1):
            last = records.get(item["name"])
            tw, reps_text, note = target_for(item, last)
            if item["name"] == "平板支撑":
                lines.append(f"{i}. {item['name']} {item['sets']}组 × {reps_text.replace(' 次', ' 秒')} · RIR {item['rir']}")
            else:
                lines.append(f"{i}. {item['name']} {item['sets']}组 × {reps_text} · RIR {item['rir']}")
            lines.append(f"   {note}")
        lines.append("━━━━━━━━━━━━")
        lines.append("组间休息：复合 2–3 min，孤立 1–2 min；每组留 1–2 次余力，最后 1 组可到 RIR 1。")
    else:
        for i, item in enumerate(day["items"], 1):
            unit = "秒" if item["name"] == "平板支撑" else "min"
            if item["name"] in ("死虫 / 鸟狗 / 侧桥", "髋 / 腘绳 / 胸椎拉伸", "拉伸 / 泡沫轴"):
                lines.append(f"{i}. {item['name']} {item['sets']}组 × {item['lo']}–{item['hi']} 次")
            else:
                lines.append(f"{i}. {item['name']} {item['lo']}–{item['hi']} {unit}")
            lines.append(f"   {item['note']}")
        lines.append("━━━━━━━━━━━━")

    supplements = plan["supplements"].get(day["type"], [])
    lines.append("💊 补剂/营养")
    for s in supplements:
        lines.append(f"· {s}")

    if day["type"] == "strength":
        lines.append("")
        lines.append("📝 练完把每个动作的「重量×次数×RIR」发我，或填 tools/训练日志模板.xlsx，下次自动加重。")
    elif day["type"] == "rest":
        lines.append("")
        lines.append("😴 今天不练：睡够 7–9 h，蛋白吃够，明天继续。")
    msg = "\n".join(lines)
    return msg


def send(message, config):
    endpoint = config.get("endpoint") or "http://127.0.0.1:14500/api/dsh-im/delivery/messages"
    payload = json.dumps({
        "botId": config["botId"],
        "targetId": config["targetId"],
        "text": message,
    }, ensure_ascii=False).encode("utf-8")
    req = urllib.request.Request(endpoint, data=payload, headers={"Content-Type": "application/json"})
    with urllib.request.urlopen(req, timeout=20) as resp:
        body = resp.read().decode("utf-8", "replace")
        print(f"HTTP {resp.status}: {body}")


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--dry", action="store_true")
    ap.add_argument("--send", action="store_true")
    ap.add_argument("--day", default=None)
    ap.add_argument("--date", default=None)
    args = ap.parse_args()

    plan = load_json(PLAN_PATH)
    date_obj = dt.date.fromisoformat(args.date) if args.date else dt.date.today()

    if args.day:
        day_key = args.day
        if day_key not in plan["days"]:
            print(f"未知的训练日：{day_key}，可选 {list(plan['days'])}", file=sys.stderr)
            sys.exit(1)
    else:
        day_key = plan["schedule"][WEEKDAY_KEYS[date_obj.weekday()]]

    day = plan["days"][day_key]
    records = read_last_records()
    message = build_message(plan, day_key, day, date_obj, records)

    print(message)
    print()
    print(f"[day={day_key}] [chars={len(message)}] [dry={args.dry}]")

    if args.send:
        config = load_json(CONFIG_PATH)
        if not config.get("botId") or not config.get("targetId"):
            print("coach_config.json 里 botId/targetId 还没填。", file=sys.stderr)
            sys.exit(2)
        send(message, config)


if __name__ == "__main__":
    main()
", "file_path": "D:\BaiduSyncdisk\000\bodybuilding\scripts\coach_push.py"}

