def candidate_endpoints(config):
    """按优先级返回候选投递地址：配置的 → DSH_WEB_URL 环境变量 → 常见端口。"""
    out = []
    ep = (config.get("endpoint") or "").strip()
    if ep and ep.lower() != "auto":
        out.append(ep)
    env = (os.environ.get("DSH_WEB_URL") or "").strip()
    if env:
        out.append(env.rstrip("/") + "/api/dsh-im/delivery/messages")
    for port in (14500, 12666, 3080):
        out.append(f"http://127.0.0.1:{port}/api/dsh-im/delivery/messages")
    seen, uniq = set(), []
    for u in out:
        if u not in seen:
            seen.add(u)
            uniq.append(u)
    return uniq


def send(message, config):
    payload = json.dumps({
        "botId": config["botId"],
        "targetId": config["targetId"],
        "text": message,
    }, ensure_ascii=False).encode("utf-8")
    last_err = None
    for endpoint in candidate_endpoints(config):
        req = urllib.request.Request(endpoint, data=payload, headers={"Content-Type": "application/json"})
        try:
            with urllib.request.urlopen(req, timeout=20) as resp:
                body = resp.read().decode("utf-8", "replace")
                print(f"HTTP {resp.status}: {body}  [{endpoint}]")
                return
        except urllib.error.HTTPError as e:
            body = e.read().decode("utf-8", "replace")
            print(f"HTTP {e.code}: {body}  [{endpoint}]", file=sys.stderr)
            raise SystemExit(3)
        except Exception as e:  # 端口不通，换下一个候选
            last_err = e
            continue
    raise SystemExit(f"所有候选地址都连不上：{last_err}")


