{"content": "param(
    [switch]$CreateTask
)

# NOTE: keep this file ASCII-only. Windows PowerShell 5.1 reads UTF-8 without BOM
# as ANSI, and CJK text can then break the parser.

$ErrorActionPreference = 'Stop'
try { [Console]::OutputEncoding = [System.Text.Encoding]::UTF8 } catch { }
$env:PYTHONIOENCODING = 'utf-8'
$base = Split-Path -Parent $PSScriptRoot

# Netdisk / antivirus may hold files briefly: retry writes.
function Write-TextWithRetry {
    param([string]$Path, [string]$Text, [int]$Attempts = 8)
    for ($i = 1; $i -le $Attempts; $i++) {
        try {
            [System.IO.File]::WriteAllText($Path, $Text, (New-Object System.Text.UTF8Encoding($false)))
            return
        } catch {
            if ($i -eq $Attempts) { throw }
            Start-Sleep -Milliseconds (300 * $i)
        }
    }
}

Write-Host "Knowledge base: $base"

# 1. find python
$cands = @()
if ($env:DSH_PYTHON) { $cands += $env:DSH_PYTHON }
$cands += (Join-Path $env:USERPROFILE '.dsh\dsh-runtimes\dsh-primary-runtime\dependencies\python\python.exe')
foreach ($name in @('python', 'python3', 'py')) {
    $c = Get-Command $name -ErrorAction SilentlyContinue
    if ($c) { $cands += $c.Source }
}
$python = $null
foreach ($c in $cands) {
    if ($c -and (Test-Path $c)) {
        try { & $c --version 2>&1 | Out-Null; $python = $c; break } catch { }
    }
}
if (-not $python) {
    throw 'No Python found. Install Python 3.10+ and tick "Add to PATH", or set $env:DSH_PYTHON.'
}
Write-Host "Python: $python"

# openpyxl is needed to read the training log
& $python -c "import openpyxl" 2>$null
if ($LASTEXITCODE -ne 0) {
    Write-Host 'Installing openpyxl ...'
    & $python -m pip install --quiet openpyxl
}

# 2. regenerate run_daily.cmd with this machine's absolute paths
$runCmd = @"
@echo off
chcp 65001 >nul
set PYTHONIOENCODING=utf-8
if not exist "%~dp0logs" mkdir "%~dp0logs"
echo ===== %date% %time% ===== >> "%~dp0logs\coach_push.log"
"$python" "%~dp0coach_push.py" --send >> "%~dp0logs\coach_push.log" 2>&1
echo exit=%ERRORLEVEL% >> "%~dp0logs\coach_push.log"
"@
Write-TextWithRetry -Path (Join-Path $PSScriptRoot 'run_daily.cmd') -Text $runCmd
Write-Host 'Updated scripts\run_daily.cmd'

# 3. normalize coach_config.json
$cfgPath = Join-Path $PSScriptRoot 'coach_config.json'
$cfg = Get-Content $cfgPath -Raw -Encoding UTF8 | ConvertFrom-Json
$cfg | Add-Member -NotePropertyName endpoint -NotePropertyValue 'auto' -Force
if (-not ($cfg.PSObject.Properties.Name -contains 'historyStart') -or -not $cfg.historyStart) {
    $cfg | Add-Member -NotePropertyName historyStart -NotePropertyValue (Get-Date -Format 'yyyy-MM-dd') -Force
}
$json = $cfg | ConvertTo-Json -Depth 4
Write-TextWithRetry -Path $cfgPath -Text $json
Write-Host 'Updated scripts\coach_config.json (endpoint=auto)'

# 4. dry run
Write-Host ''
Write-Host '---------- dry run ----------'
& $python (Join-Path $PSScriptRoot 'coach_push.py') --dry
if ($LASTEXITCODE -ne 0) { throw 'coach_push.py --dry failed' }
Write-Host '-----------------------------'

# 5. scheduled task
if (-not $cfg.botId -or -not $cfg.targetId) {
    Write-Host ''
    Write-Host 'WARNING: coach_config.json has no botId/targetId yet.'
    Write-Host 'Bind WeChat in DSH (Settings -> IM bots -> WeChat), send the bot a message,'
    Write-Host 'create a delivery target, then paste {botId,targetId} into scripts\coach_config.json.'
    Write-Host 'Task NOT created. Re-run with -CreateTask after filling the config.'
    exit 0
}

if ($CreateTask) {
    $tr = 'cmd /c "' + (Join-Path $PSScriptRoot 'run_daily.cmd') + '"'
    schtasks /Create /F /SC DAILY /ST 14:00 /TN 'BodybuildingCoach' /TR $tr
    $s = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -StartWhenAvailable
    Set-ScheduledTask -TaskName 'BodybuildingCoach' -Settings $s | Out-Null
    schtasks /Query /TN 'BodybuildingCoach' /FO LIST
} else {
    Write-Host ''
    Write-Host 'Task not created. Run again with:  .\setup_new_pc.ps1 -CreateTask'
}
", "file_path": "D:\BaiduSyncdisk\000\bodybuilding\scripts\setup_new_pc.ps1"}

